  ('93a28021-7e1c-4519-a939-d16d259c65fa', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'bd87a675-d7ff-47b2-95ba-6cb850fa46fc', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਧਿਆਪਕਾ - ਬੱਚਿਓ! ਤੁਸੀਂ ਸ਼ਾਮ ਦੇ ਸਮੇਂ ਕੀ ਕਰਦੇ ਹੋ? ਪਹਿਲਾ ਬੱਚਾ - ਮੈਡਮ ਜੀ, ਮੈਂ ਆਪਣਾ ਸਕੂਲ ਦਾ ਕੰਮ ਮੁਕਾ ਕੇ ਆਪਣੇ ਭਰਾ ਨਾਲ ਵੀਡੀਓ ਗੇਮ ਖੇਡਦਾ ਹਾਂ। ਅਧਿਆਪਕਾ - ਬੇਟਾ! ਤੁਹਾਨੂੰ ਫੋਨ ਤੇ ਖੇਡਾਂ ਖੇਡਣ ਦੀ ਬਜਾਏ ਬਾਹਰ ਨਿਕਲਣਾ ਚਾਹੀਦਾ ਹੈ ਤੇ ਕੁਦਰਤ ਦੇ ਨਜ਼ਾਰਿਆਂ ਦਾ ਅਨੰਦ ਲੈਣਾ ਚਾਹੀਦਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-368Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
  ('b1a3b01f-84ab-4c8d-9b18-a90bd65f1064', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'bd87a675-d7ff-47b2-95ba-6cb850fa46fc', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੂਸਰਾ ਬੱਚਾ - ਮੈਡਮ ਜੀ, ਮੈਂ ਪਾਰਕ ਵਿੱਚ ਜਾ ਕੇ ਖੇਡਦਾ ਹਾਂ। ਉੱਥੇ ਲੱਗੇ ਰੰਗ-ਬਿਰੰਗੇ ਫੁੱਲ ਮੈਨੂੰ ਬਹੁਤ ਪਸੰਦ ਹਨ। ਅਧਿਆਪਕਾ - ਬੇਟਾ! ਇਹ ਕੁਦਰਤੀ ਨਜ਼ਾਰੇ ਵੇਖਣ ਨੂੰ ਤਾਂ ਸੋਹਣੇ ਲੱਗਦੇ ਹੀ ਹਨ, ਇਸਦੇ ਨਾਲ-ਨਾਲ ਇਹ ਸਾਨੂੰ ਕਈ ਸਬਕ ਵੀ ਸਿਖਾਉਂਦੇ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-368Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 10, NULL),
