  ('4ea7a3cd-2ae3-47ce-b188-0c7ceeb7b6e6', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'bd87a675-d7ff-47b2-95ba-6cb850fa46fc', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲੰਮੀਆਂ ਤਾਣ ਕੇ ਸੁੱਤਿਆਂ, ਮੰਜ਼ਿਲ ਮਿਲਦੀ ਨਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-368Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('aa723cd0-d8c6-4af0-8c5f-4650a76fbea4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'bd87a675-d7ff-47b2-95ba-6cb850fa46fc', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਧਿਆਪਕਾ - ਬੱਚਿਓ! ਤੁਸੀਂ ਸ਼ਾਮ ਦੇ ਸਮੇਂ ਕੀ ਕਰਦੇ ਹੋ? ਪਹਿਲਾ ਬੱਚਾ - ਮੈਡਮ ਜੀ, ਮੈਂ ਆਪਣਾ ਸਕੂਲ ਦਾ ਕੰਮ ਮੁਕਾ ਕੇ ਆਪਣੇ ਭਰਾ ਨਾਲ ਵੀਡੀਓ ਗੇਮ ਖੇਡਦਾ ਹਾਂ। ਅਧਿਆਪਕਾ - ਬੇਟਾ! ਤੁਹਾਨੂੰ ਫੋਨ ਤੇ ਖੇਡਾਂ ਖੇਡਣ ਦੀ ਬਜਾਏ ਬਾਹਰ ਨਿਕਲਣਾ ਚਾਹੀਦਾ ਹੈ ਤੇ ਕੁਦਰਤ ਦੇ ਨਜ਼ਾਰਿਆਂ ਦਾ ਅਨੰਦ ਲੈਣਾ ਚਾਹੀਦਾ ਹੈ। ਦੂਸਰਾ ਬੱਚਾ - ਮੈਡਮ ਜੀ, ਮੈਂ ਪਾਰਕ ਵਿੱਚ ਜਾ ਕੇ ਖੇਡਦਾ ਹਾਂ। ਉੱਥੇ ਲੱਗੇ ਰੰਗ-ਬਿਰੰਗੇ ਫੁੱਲ ਮੈਨੂੰ ਬਹੁਤ ਪਸੰਦ ਹਨ। ਅਧਿਆਪਕਾ - ਬੇਟਾ! ਇਹ ਕੁਦਰਤੀ ਨਜ਼ਾਰੇ ਵੇਖਣ ਨੂੰ ਤਾਂ ਸੋਹਣੇ ਲੱਗਦੇ ਹੀ ਹਨ, ਇਸਦੇ ਨਾਲ-ਨਾਲ ਇਹ ਸਾਨੂੰ ਕਈ ਸਬਕ ਵੀ ਸਿਖਾਉਂਦੇ ਹਨ। ਤੀਸਰਾ ਬੱਚਾ - ਸਬਕ? ਉਹ ਕਿਹੜੇ ਮੈਡਮ ਜੀ? ਅਧਿਆਪਕਾ - ਕੁਦਰਤ ਦੀ ਹਰ ਚੀਜ਼ ਸਾਨੂੰ ਕੋਈ ਨਾ ਕੋਈ ਸਬਕ ਜ਼ਰੂਰ ਦਿੰਦੀ ਹੈ। ਜਿਵੇਂ- ਫੁੱਲ ਸਾਨੂੰ ਮਹਿਕਾਂ ਵੰਡਣ, ਸੂਰਜ ਹਨੇਰਾ ਦੂਰ ਕਰਨ ਦਾ, ਪੰਛੀ ਉੱਚੀਆਂ ਉਡਾਰੀਆਂ ਭਰਨ ਆਦਿ ਦੇ ਸਬਕ ਦਿੰਦੇ ਹਨ। ਆਓ! ਤੁਹਾਨੂੰ 'ਕੁਦਰਤ ਦੇ ਸਬਕ' ਕਵਿਤਾ ਪੜ੍ਹਾ ਕੇ ਇਹਨਾਂ ਬਾਰੇ ਹੋਰ ਜਾਣਕਾਰੀ ਦੇਵਾਂ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-368Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 35, NULL),
  ('ff8bfa99-2a9a-4f83-9417-6b9f00361607', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'bd87a675-d7ff-47b2-95ba-6cb850fa46fc', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸੂਰਜ ਆਖੇ ਚਮਕਿਉ, ਮੇਟ ਦਿਉ ਅੰਧਕਾਰ, ਨ੍ਹੇਰਾ ਝੂਠ-ਫਰੇਬ ਦਾ ਕਰ ਨਾ ਜਾਵੇ ਵਾਰ। ਰੁੱਖਾਂ ਕੋਲੋਂ ਸਿੱਖੀਏ, ਬਣਨਾ ਕਿੰਝ ਦਰਵੇਸ਼, ਝੁਕਤ, ਅਹਿਮ, ਬਾਰਸ਼ਾਂ, ਝੱਲਦੇ ਰਹਿਣ ਹਮੇਸ਼। ਫੁੱਲ ਸਿਖਾਉਂਦੇ ਮਹਿਕਣਾ, ਰਹਿ ਕੰਡਿਆਂ ਦੇ ਸੰਗ, ਮਨ ਵਿੱਚ ਜਿਊਂਦੀ ਰੱਖਣਾ, ਹਿੰਮਤ, ਸਿਦਕ, ਉਮੰਗ। ਪੌਣਾਂ ਦੇਣ ਸੁਨੇਹੜੇ, ਰੱਖਣੀ ਸੋਚ ਆਜ਼ਾਦ, ਪਿੰਜਰੇ ਵਿੱਚ ਮਨੁੱਖਤਾ, ਹੁੰਦੀ ਨਹੀਂ ਆਬਾਦ। ਦੱਸਣ ਦਰਿਆ ਸੂਕਦੇ, ਜੋ ਪਾਉਣੀ ਵਾਹ ਵਾਹ, ਵਹਿਣਾ ਭੰਨ ਰੁਕਾਵਟਾਂ, ਲੱਭੋ ਆਪਣਾ ਰਾਹ। ਉੱਚੀਆਂ ਭਰਨ ਉਡਾਰੀਆਂ, ਪੰਛੀ ਗਏ ਸੁਣਾ, ਲੰਮੀਆਂ ਤਾਣ ਕੇ ਸੁੱਤਿਆਂ, ਮੰਜ਼ਿਲ ਮਿਲਦੀ ਨਾ। ਸਿੱਖੋ ਸਮੁੰਦਰ ਦੇ ਭਰੇ, ਰੱਖੋ ਸੋਚ ਵਿਸ਼ਾਲ, ਜਿਹੜੇ ਵੱਡਾ ਸੋਚਦੇ ਓਹੀ ਕਰਨ ਕਮਾਲ। ਡੂੰਘਾ ਚਿੰਤ ਵਸਾਉਣਾ, ਕੁਦਰਤ ਵੰਡੇ ਗਿਆਨ, ਜਿਹੜੇ ਮਨ ਲਾ ਸਿੱਖਦੇ, ਓਹੀ ਲੋਕ ਮਹਾਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-368Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('2d1700ec-057d-4ed0-be28-cab0a58172d8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'bd87a675-d7ff-47b2-95ba-6cb850fa46fc', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸੂਰਜ ਆਖੇ ਚਮਕਿਉ, ਮੇਟ ਦਿਉ ਅੰਧਕਾਰ, ਨ੍ਹੇਰਾ ਝੂਠ-ਫਰੇਬ ਦਾ ਕਰ ਨਾ ਜਾਵੇ ਵਾਰ। ਰੁੱਖਾਂ ਕੋਲੋਂ ਸਿੱਖੀਏ, ਬਣਨਾ ਕਿੰਝ ਦਰਵੇਸ਼, ਝੁਕਤ, ਅਹਿਮ, ਬਾਰਸ਼ਾਂ, ਝੱਲਦੇ ਰਹਿਣ ਹਮੇਸ਼। ਫੁੱਲ ਸਿਖਾਉਂਦੇ ਮਹਿਕਣਾ, ਰਹਿ ਕੰਡਿਆਂ ਦੇ ਸੰਗ, ਮਨ ਵਿੱਚ ਜਿਊਂਦੀ ਰੱਖਣਾ, ਹਿੰਮਤ, ਸਿਦਕ, ਉਮੰਗ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-368Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
