  ('f8dd05e3-1794-4409-926e-d692879dc7c7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'bd87a675-d7ff-47b2-95ba-6cb850fa46fc', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦੱਸਣ ਦਰਿਆ ਸੂਕਦੇ, ਜੋ ਪਾਉਣੀ ਵਾਹ ਵਾਹ, ਵਹਿਣਾ ਭੰਨ ਰੁਕਾਵਟਾਂ, ਲੱਭੋ ਆਪਣਾ ਰਾਹ। ਉੱਚੀਆਂ ਭਰਨ ਉਡਾਰੀਆਂ, ਪੰਛੀ ਗਏ ਸੁਣਾ, ਲੰਮੀਆਂ ਤਾਣ ਕੇ ਸੁੱਤਿਆਂ, ਮੰਜ਼ਿਲ ਮਿਲਦੀ ਨਾ। ਸਿੱਖੋ ਸਮੁੰਦਰ ਦੇ ਭਰੇ, ਰੱਖੋ ਸੋਚ ਵਿਸ਼ਾਲ, ਜਿਹੜੇ ਵੱਡਾ ਸੋਚਦੇ ਓਹੀ ਕਰਨ ਕਮਾਲ। ਡੂੰਘਾ ਚਿੰਤ ਵਸਾਉਣਾ, ਕੁਦਰਤ ਵੰਡੇ ਗਿਆਨ, ਜਿਹੜੇ ਮਨ ਲਾ ਸਿੱਖਦੇ, ਓਹੀ ਲੋਕ ਮਹਾਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-368Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('25305653-6aff-4450-96e7-cbba22149dc4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', 'bd87a675-d7ff-47b2-95ba-6cb850fa46fc', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸੂਰਜ ਆਖੇ ਚਮਕਿਉ, ਮੇਟ ਦਿਉ ਅੰਧਕਾਰ, ਨ੍ਹੇਰਾ ਝੂਠ-ਫਰੇਬ ਦਾ ਕਰ ਨਾ ਜਾਵੇ ਵਾਰ। ਰੁੱਖਾਂ ਕੋਲੋਂ ਸਿੱਖੀਏ, ਬਣਨਾ ਕਿੰਝ ਦਰਵੇਸ਼, ਝੁਕਤ, ਅਹਿਮ, ਬਾਰਸ਼ਾਂ, ਝੱਲਦੇ ਰਹਿਣ ਹਮੇਸ਼। ਫੁੱਲ ਸਿਖਾਉਂਦੇ ਮਹਿਕਣਾ, ਰਹਿ ਕੰਡਿਆਂ ਦੇ ਸੰਗ, ਮਨ ਵਿੱਚ ਜਿਊਂਦੀ ਰੱਖਣਾ, ਹਿੰਮਤ, ਸਿਦਕ, ਉਮੰਗ। ਪੌਣਾਂ ਦੇਣ ਸੁਨੇਹੜੇ, ਰੱਖਣੀ ਸੋਚ ਆਜ਼ਾਦ, ਪਿੰਜਰੇ ਵਿੱਚ ਮਨੁੱਖਤਾ, ਹੁੰਦੀ ਨਹੀਂ ਆਬਾਦ। ਦੱਸਣ ਦਰਿਆ ਸੂਕਦੇ, ਜੋ ਪਾਉਣੀ ਵਾਹ ਵਾਹ, ਵਹਿਣਾ ਭੰਨ ਰੁਕਾਵਟਾਂ, ਲੱਭੋ ਆਪਣਾ ਰਾਹ। ਉੱਚੀਆਂ ਭਰਨ ਉਡਾਰੀਆਂ, ਪੰਛੀ ਗਏ ਸੁਣਾ, ਲੰਮੀਆਂ ਤਾਣ ਕੇ ਸੁੱਤਿਆਂ, ਮੰਜ਼ਿਲ ਮਿਲਦੀ ਨਾ। ਸਿੱਖੋ ਸਮੁੰਦਰ ਦੇ ਭਰੇ, ਰੱਖੋ ਸੋਚ ਵਿਸ਼ਾਲ, ਜਿਹੜੇ ਵੱਡਾ ਸੋਚਦੇ ਓਹੀ ਕਰਨ ਕਮਾਲ। ਡੂੰਘਾ ਚਿੰਤ ਵਸਾਉਣਾ, ਕੁਦਰਤ ਵੰਡੇ ਗਿਆਨ, ਜਿਹੜੇ ਮਨ ਲਾ ਸਿੱਖਦੇ, ਓਹੀ ਲੋਕ ਮਹਾਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-55-368Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL);
